// Parse incoming OS data — n8n Webhook node nests the POST payload under .body
const data = $input.first().json.body || $input.first().json;

// Validate required fields
if (!data.os_number || !data.pts) {
  throw new Error('Campos obrigatorios faltando: os_number, pts');
}

// Format date for filename
const dateStr = (data.data || '').replace(/\//g, '-');

// Prepare structured data
return {
  ...data,
  filename: `OS_${data.os_number}_${dateStr}.pdf`,
  timestamp: new Date().toISOString()
};

const prev = $('Parse & Validate').first().json;
const llmResponse = $input.first().json;
const descResumida = llmResponse?.choices?.[0]?.message?.content || prev.descricao_detalhada || prev.descricao;

return { ...prev, descricao_resumida: (descResumida || '').trim() };

const item = $input.first().json;
const chatIds = ['5118460498', '8971897435', '8676263350'];
return chatIds.map((chatId) => ({ ...item, chat_id: chatId }));
